ves":["Jogging","Snatch","Clean"]},{"name":"Snatch","alternatives":["Clean","Jogging","Wall Ball"]},{"name":"Clean","alternatives":["Snatch","Jogging","Wall Ball"]},{"name":"Turkish Get-Up","alternatives":["Farmer’s Walk","Kettlebell Swing"]},{"name":"Crab Reach (Thoracic Bridge)","alternatives":["Turkish Get-Up","Farmer’s Walk","Kettlebell Swing"]},{"name":"Sled Pull/Push","alternatives":["Turkish Get-Up","Farmer’s Walk","Kettlebell Swing"]},{"name":"Farmer’s Walk","alternatives":["Turkish Get-Up","Kettlebell Swing"]},{"name":"90s Transition","alternatives":["Turkish Get-Up","Farmer’s Walk","Kettlebell Swing"]},{"name":"Prone Swimmer","alternatives":["Turkish Get-Up","Farmer’s Walk","Kettlebell Swing"]},{"name":"Kettlebell Swing","alternatives":["Turkish Get-Up","Farmer’s Walk"]},{"name":"left over db","alternatives":["Turkish Get-Up","Farmer’s Walk","Kettlebell Swing"]},{"name":"Serratus Punches Supine","alternatives":["Turkish Get-Up","Farmer’s Walk","Kettlebell Swing"]}]$ex$::jsonb) AS x(name text, alternatives text[])
  JOIN exercises e ON lower(trim(e.name)) = lower(trim(x.name))
  CROSS JOIN LATERAL unnest(coalesce(x.alternatives, '{}')) WITH ORDINALITY AS t(alt, ord)
  JOIN exercises a ON lower(trim(a.name)) = lower(trim(t.alt)) AND a.id <> e.id
 WHERE NOT EXISTS (SELECT 1 FROM exercise_alternatives z WHERE z.exercise_id = e.id)
ON CONFLICT DO NOTHING;

COMMIT;
